pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient, uint256 amount, uint8 n) public {
        vm.assume(n > 0);
        vm.assume(n <= 50);
        address vader = address(0x1);
        address usdv = address(0x2);
        address vault = address(0x3);
        c.init(vader, usdv, vault);
        vm.prank(address(0x100));
        for(uint8 i = 0; i < n; i++) {
            c.newGrantProposal(recipient, amount);
        }
        assertTrue(c.proposalCount() == n);
    }
}
